#!/usr/bin/env node
/**
 * Builds frontend/src/components/widgets/worldOutline.ts, the land outline drawn
 * behind the Login Locations markers. Run it only to change the outline; the
 * app ships the generated file and calls no map service at run time.
 *
 * Data: Natural Earth 1:110m land (public domain), as redistributed in
 * world-atlas (ISC). Drawing: d3-geo (ISC), which also clips land that
 * crosses the date line and closes Antarctica around the pole. None of these
 * are Helios dependencies; install them in a scratch folder and pass its path:
 *
 *   npm install --prefix <folder> --ignore-scripts \
 *     world-atlas@2.0.2 topojson-client@3.1.0 d3-geo@3.1.1 d3-array@3.2.4
 *   node frontend/scripts/build-world-outline.mjs <folder>
 *
 * The outline uses the marker frame in loginMapProjection.ts: equirectangular,
 * 1000 x 500, longitude -180..180 left to right, latitude 90..-90 top to bottom.
 */
import { readFileSync, writeFileSync } from 'fs';
import { createRequire } from 'module';
import { dirname, join } from 'path';
import { fileURLToPath, pathToFileURL } from 'url';

const folder = process.argv[2];
if (!folder) {
  console.error('usage: node build-world-outline.mjs <folder with world-atlas, topojson-client, d3-geo installed>');
  process.exit(1);
}
const require = createRequire(join(folder, 'noop.js'));
const load = (name) => import(pathToFileURL(require.resolve(name)).href);

const { geoEquirectangular, geoPath } = await load('d3-geo');
const { feature } = await load('topojson-client');
const versionOf = (name) =>
  JSON.parse(readFileSync(join(folder, 'node_modules', name, 'package.json'), 'utf8')).version;
const topology = JSON.parse(
  readFileSync(join(folder, 'node_modules', 'world-atlas', 'land-110m.json'), 'utf8')
);

const WIDTH = 1000;
const HEIGHT = 500;
// Equirectangular with this scale and centre gives x = (lng + 180) / 360 * WIDTH
// and y = (90 - lat) / 180 * HEIGHT, the same as latLongToSvg.
const projection = geoEquirectangular()
  .scale(WIDTH / (2 * Math.PI))
  .translate([WIDTH / 2, HEIGHT / 2]);
// Whole units: the map is drawn at most about 400 px wide, so one unit is under half a pixel.
const path = geoPath(projection).digits(0);

const d = path(feature(topology, topology.objects.land));
if (!d) throw new Error('d3-geo produced no outline');

const out = `// Generated by frontend/scripts/build-world-outline.mjs. Do not edit by hand.
// Land outline from Natural Earth 1:110m (public domain, naturalearthdata.com),
// via world-atlas ${versionOf('world-atlas')} (Copyright 2013-2019 Michael Bostock, ISC licence),
// drawn with d3-geo ${versionOf('d3-geo')} (ISC). Licence texts: docs/guides/login-locations.md.
// Equirectangular, ${WIDTH} x ${HEIGHT} frame, the same as loginMapProjection.ts.
export const WORLD_OUTLINE_PATH =
  '${d}';
`;

const target = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'components', 'widgets', 'worldOutline.ts');
writeFileSync(target, out);
console.log(`wrote ${target}: ${out.length} bytes`);
